  toggle(name){const panel=document.getElementById(name);if(!panel)return;const open=panel.classList.contains('active');document.querySelectorAll('.overlay').forEach(item=>item.classList.remove('active'));if(open)this.closeMenu();else if(this.beginMenu())panel.classList.add('active');if(name==='inventory-panel')renderInventory();if(name==='quests-panel')this.renderQuests();if(name==='map-panel')this.renderMap();if(name==='profile-panel')this.renderProfile()}
