  updateDashboard(){const dashboard=document.getElementById('train-dashboard');if(!dashboard)return;dashboard.classList.toggle('active',this.train.inTrain);for(const [key,value]of Object.entries({speed:this.train.speed.toFixed(1),distance:(this.train.routeProgress/1000).toFixed(1),fuel:Math.round(this.train.fuel),integrity:Math.round(this.train.integrity)})){const element=document.getElementById(`train-${key}`);if(element)element.textContent=value}const destination=document.getElementById('train-destination');if(destination)destination.textContent=`DESTINO: ${this.currentRegion.name.toUpperCase()}`}
  updatePrompt(){const prompt=document.getElementById('prompt');if(!prompt)return;let text='';if(this.train.inTrain)text='F sair • Q acelerar • E frear';else if(distance(this.player.pos,this.train)<2.8)text='E entrar / abastecer locomotiva';else if(!this.brokenRepaired&&Math.hypot(this.player.pos.x-14,this.player.pos.z-10)<3.5)text='R reparar trilho • 3 sucata + 2 lingotes';else{const resource=this.resources.find(item=>!item.depleted&&distance(item,this.player.pos)<2.4);const station=this.stations.find(item=>distance(item,this.player.pos)<2.4);const npc=this.npcs.find(item=>distance(item,this.player.pos)<2.4);if(resource)text=`E coletar ${resource.type}`;else if(station)text=`E usar ${station.type.replaceAll('_',' ')}`;else if(npc)text=`E conversar com ${npc.name}`}prompt.textContent=text}

  worldToScreen(x,z){return{x:(x-this.camera.x)*this.camera.zoom+this.width/2,y:(z-this.camera.z)*this.camera.zoom+this.height/2}}
  screenToWorld(x,y){return{x:(x-this.width/2)/this.camera.zoom+this.camera.x,z:(y-this.height/2)/this.camera.zoom+this.camera.z}}
  visible(x,z,padding=3){const point=this.worldToScreen(x,z),pad=padding*this.camera.zoom;return point.x>-pad&&point.x<this.width+pad&&point.y>-pad&&point.y<this.height+pad}
