  drawStation(ctx){if(!this.visible(2,12,5))return;const point=this.worldToScreen(2,12),scale=this.camera.zoom;ctx.save();ctx.translate(point.x,point.y);ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(0,scale*.35,scale*3.2,scale*1.8,0,0,TAU);ctx.fill();const roof=ctx.createLinearGradient(0,-scale*2,0,scale*1.5);roof.addColorStop(0,'#8d4b31');roof.addColorStop(1,'#442319');ctx.fillStyle=roof;ctx.strokeStyle='#c8955f';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-scale*2.7,-scale*1.65,scale*5.4,scale*3.3,scale*.15);ctx.fill();ctx.stroke();ctx.strokeStyle='rgba(255,224,170,.25)';for(let x=-2.2;x<2.5;x+=.55){ctx.beginPath();ctx.moveTo(x*scale,-scale*1.5);ctx.lineTo(x*scale,scale*1.5);ctx.stroke()}ctx.fillStyle='#251914';ctx.fillRect(-scale*.48,-scale*1.65,scale*.96,scale*3.3);ctx.fillStyle='#d8b368';ctx.font=`700 ${Math.max(9,scale*.28)}px sans-serif`;ctx.textAlign='center';ctx.fillText('ESTAÇÃO',0,-scale*1.85);ctx.restore()}
  drawLandmarks(ctx){for(const landmark of this.regionalWorld.landmarks){if(!this.visible(landmark.x,landmark.z,3))continue;const point=this.worldToScreen(landmark.x,landmark.z),scale=this.camera.zoom,type=landmark.type;ctx.save();ctx.translate(point.x,point.y);if(type.includes('river')){ctx.lineCap='round';ctx.strokeStyle='rgba(45,67,48,.48)';ctx.lineWidth=scale*1.25;ctx.beginPath();ctx.moveTo(-scale*2.1,-scale*.7);ctx.bezierCurveTo(-scale*.9,-scale*1.15,scale*.35,scale*.95,scale*2.1,scale*.45);ctx.stroke();ctx.strokeStyle='#487b86';ctx.lineWidth=scale*.82;ctx.stroke();ctx.strokeStyle='rgba(180,222,223,.36)';ctx.lineWidth=scale*.12;ctx.stroke()}else if(type.includes('cave')||type.includes('tunnel')||type.includes('mine')){ctx.fillStyle='rgba(0,0,0,.38)';ctx.beginPath();ctx.ellipse(0,scale*.25,scale*1.25,scale*.72,0,0,TAU);ctx.fill();ctx.strokeStyle='#756b5e';ctx.lineWidth=scale*.3;ctx.beginPath();ctx.arc(0,0,scale*.72,Math.PI,TAU);ctx.stroke();ctx.fillStyle='#101414';ctx.beginPath();ctx.ellipse(0,scale*.1,scale*.58,scale*.45,0,0,TAU);ctx.fill()}else if(type.includes('tower')){ctx.fillStyle='rgba(0,0,0,.34)';ctx.beginPath();ctx.ellipse(0,scale*.38,scale*.8,scale*.48,0,0,TAU);ctx.fill();ctx.fillStyle='#5d554b';ctx.strokeStyle='#a6977b';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,scale*.58,0,TAU);ctx.fill();ctx.stroke();ctx.fillStyle='#292b29';ctx.beginPath();ctx.arc(0,0,scale*.27,0,TAU);ctx.fill();for(let index=0;index<4;index++){const angle=index/4*TAU;ctx.strokeStyle='#b0a17e';ctx.beginPath();ctx.moveTo(Math.cos(angle)*scale*.28,Math.sin(angle)*scale*.28);ctx.lineTo(Math.cos(angle)*scale*.75,Math.sin(angle)*scale*.75);ctx.stroke()}}else{ctx.fillStyle='rgba(0,0,0,.34)';ctx.beginPath();ctx.ellipse(0,scale*.35,scale*1.3,scale*.72,0,0,TAU);ctx.fill();const roof=ctx.createLinearGradient(0,-scale*.85,0,scale*.85);roof.addColorStop(0,type.includes('laboratory')?'#71818a':type.includes('ruin')?'#69635a':'#76503c');roof.addColorStop(1,type.includes('laboratory')?'#35444c':type.includes('ruin')?'#3d3933':'#3b271f');ctx.fillStyle=roof;ctx.strokeStyle='#b79a72';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(-scale*1.08,-scale*.76,scale*2.16,scale*1.52,scale*.12);ctx.fill();ctx.stroke();ctx.strokeStyle='rgba(240,220,180,.2)';for(let x=-.8;x<1;x+=.4){ctx.beginPath();ctx.moveTo(x*scale,-scale*.68);ctx.lineTo(x*scale,scale*.68);ctx.stroke()}ctx.fillStyle='#1b211f';ctx.fillRect(-scale*.22,-scale*.76,scale*.44,scale*1.52)}if(landmark.discovered){ctx.fillStyle='#f5d77b';ctx.shadowColor='#000';ctx.shadowBlur=3;ctx.font=`700 ${Math.max(9,scale*.23)}px sans-serif`;ctx.textAlign='center';ctx.fillText(type.replaceAll('_',' '),0,-scale*1.15);ctx.shadowBlur=0}ctx.restore()}}
  drawResource(ctx,node){if(node.depleted||!node.mesh.visible||!this.visible(node.x,node.z,2))return;const point=this.worldToScreen(node.x,node.z),scale=this.camera.zoom,ratio=node.hp/node.maxHp;ctx.save();ctx.translate(point.x,point.y);ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(0,scale*.25,scale*.7,scale*.32,0,0,TAU);ctx.fill();if(node.type==='tree'&&this.assets.tree){ctx.drawImage(this.assets.tree,-scale*.94,-scale*.88,scale*1.88,scale*1.72)}else if(['rock','coal','iron_ore','copper_ore','titanium_ore'].includes(node.type)&&this.assets.rock){const filters={rock:'none',coal:'grayscale(1) brightness(.28) contrast(1.25)',iron_ore:'sepia(.8) saturate(2.1) hue-rotate(330deg)',copper_ore:'sepia(.9) saturate(2.4) hue-rotate(345deg)',titanium_ore:'grayscale(.35) saturate(1.8) hue-rotate(185deg)'};ctx.filter=filters[node.type]||'none';ctx.drawImage(this.assets.rock,-scale*.75,-scale*.52,scale*1.5,scale);ctx.filter='none'}else if(node.type==='tree'){ctx.fillStyle='#3f2a1b';ctx.beginPath();ctx.arc(0,0,scale*.28,0,TAU);ctx.fill();for(let index=0;index<5;index++){const angle=index/5*TAU,radius=scale*(.35+(index%2)*.15);ctx.fillStyle=index%2?'#26452a':'#345c32';ctx.beginPath();ctx.arc(Math.cos(angle)*radius*.55,Math.sin(angle)*radius*.55,scale*.48,0,TAU);ctx.fill()}}else if(node.type==='herbs'){ctx.strokeStyle='#65a96f';ctx.lineWidth=Math.max(2,scale*.08);for(let index=0;index<6;index++){const angle=index/6*TAU;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(angle)*scale*.48,Math.sin(angle)*scale*.48);ctx.stroke()}}else{ctx.fillStyle=RESOURCE_COLORS[node.type]||'#777';ctx.strokeStyle='rgba(230,220,195,.36)';ctx.lineWidth=1.5;ctx.beginPath();for(let index=0;index<7;index++){const angle=index/7*TAU,radius=scale*(index%2?.42:.6);const x=Math.cos(angle)*radius,y=Math.sin(angle)*radius;if(index===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.closePath();ctx.fill();ctx.stroke();if(['crystal','ember_core'].includes(node.type)){ctx.shadowColor=RESOURCE_COLORS[node.type];ctx.shadowBlur=14;ctx.stroke()}}if(ratio<1){ctx.strokeStyle='#f2ca62';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,scale*.75,-Math.PI/2,-Math.PI/2+TAU*ratio);ctx.stroke()}ctx.restore()}
